SELECT *
FROM employees
WHERE manager_id = NULL;

SELECT MAX(salary)
FROM employees
WHERE salary < (SELECT MAX(salary) FROM employees);

SELECT *
FROM customers
WHERE id NOT IN (SELECT customer_id FROM orders);

SELECT customer_id, order_date, amount,
       SUM(amount) OVER (
         PARTITION BY customer_id
         ORDER BY order_date
       ) AS running
FROM orders;
